export const getProjectTerminalTheme = (name: string): ProjectTerminalTheme => {
  if (name === ACCENT_LIGHT_THEME) {
    return resolveAccentLightTheme()
  }
  return projectTerminalThemes[name] || projectTerminalThemes.midnight
}

export const getProjectTerminalContainerStyle = (name: string): Record<string, string> => {
  if (name === ACCENT_LIGHT_THEME) {
    return {
      backgroundColor: '#ffffff',
      backgroundImage:
        'linear-gradient(270deg, var(--el-color-primary-light-9) 0%, var(--el-color-primary-light-9) 98%, #ffffff 100%)',
    }
  }

  return {
    backgroundColor: getProjectTerminalTheme(name).background,
  }
}
